#ifndef __ARCH_ARM64_SRC_S6_HARDWARE_S6_UART_H
#define __ARCH_ARM64_SRC_S6_HARDWARE_S6_UART_H

#define S6_UART_WFIFO_OFFSET       0x00
#define S6_UART_RFIFO_OFFSET       0x04
#define S6_UART_CONTROL_OFFSET     0x08
#define S6_UART_STATUS_OFFSET      0x0c
#define S6_UART_MISC_OFFSET        0x10
#define S6_UART_REG5_OFFSET        0x14

#define S6_UART_CONTROL_TX_EN      (1u << 12)
#define S6_UART_CONTROL_RX_EN      (1u << 13)
#define S6_UART_CONTROL_TWO_WIRE   (1u << 15)
#define S6_UART_CONTROL_STOP_2     (1u << 16)
#define S6_UART_CONTROL_PARITY_ODD (1u << 18)
#define S6_UART_CONTROL_PARITY_EN  (1u << 19)
#define S6_UART_CONTROL_DATA_LEN_MASK  (3u << 20)
#define S6_UART_CONTROL_DATA_LEN_8BIT  (0u << 20)
#define S6_UART_CONTROL_DATA_LEN_7BIT  (1u << 20)
#define S6_UART_CONTROL_DATA_LEN_6BIT  (2u << 20)
#define S6_UART_CONTROL_DATA_LEN_5BIT  (3u << 20)
#define S6_UART_CONTROL_TX_RST     (1u << 22)
#define S6_UART_CONTROL_RX_RST     (1u << 23)
#define S6_UART_CONTROL_CLR_ERR    (1u << 24)
#define S6_UART_CONTROL_RX_INT_EN  (1u << 27)
#define S6_UART_CONTROL_TX_INT_EN  (1u << 28)

#define S6_UART_STATUS_PARITY_ERR  (1u << 16)
#define S6_UART_STATUS_FRAME_ERR   (1u << 17)
#define S6_UART_STATUS_TX_WERR     (1u << 18)
#define S6_UART_STATUS_RX_EMPTY    (1u << 20)
#define S6_UART_STATUS_TX_FULL     (1u << 21)
#define S6_UART_STATUS_TX_EMPTY    (1u << 22)
#define S6_UART_STATUS_RX_OVERFLOW (1u << 24)

#define S6_UART_REG5_BAUD_MASK     0x007fffffu
#define S6_UART_REG5_USE_NEW_BAUD  (1u << 23)
#define S6_UART_REG5_USE_XTAL      (1u << 24)
#define S6_UART_REG5_XTAL_DIV2     (1u << 27)

#define S6_UART_MISC_RX_LEVEL(n)   ((n) & 0xffu)
#define S6_UART_MISC_TX_LEVEL(n)   (((n) & 0xffu) << 8)

#define S6_UART_BAUD_CLOCK         12000000u
#define S6_UART_BAUD_DIVISOR(baud) \
  ((S6_UART_BAUD_CLOCK + ((baud) / 2u)) / (baud) - 1u)

#endif /* __ARCH_ARM64_SRC_S6_HARDWARE_S6_UART_H */
########## arch/arm64/src/s6/hardware/s6_viu.h
/****************************************************************************
 * arch/arm64/src/s6/hardware/s6_viu.h
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 ****************************************************************************/

#ifndef __ARCH_ARM64_SRC_S6_HARDWARE_S6_VIU_H
#define __ARCH_ARM64_SRC_S6_HARDWARE_S6_VIU_H

/* Vendor "VCBUS" space: physical address = base + (index << 2). */

#define S6_VCBUS_BASE                 0xff000000u
#define S6_VCBUS_ADDR(idx)            (S6_VCBUS_BASE + ((idx) << 2))

/* VIU_OSD1 (fetched by the linear MIF, no canvas). */

#define S6_VIU_OSD1_CTRL_STAT         S6_VCBUS_ADDR(0x1a10)
#define S6_VIU_OSD1_BLK0_CFG_W1       S6_VCBUS_ADDR(0x1a1c)
#define S6_VIU_OSD1_BLK0_CFG_W2       S6_VCBUS_ADDR(0x1a1d)
#define S6_VIU_OSD1_BLK0_CFG_W3       S6_VCBUS_ADDR(0x1a1e)
#define S6_VIU_OSD1_BLK0_CFG_W4       S6_VCBUS_ADDR(0x1a13)
#define S6_VIU_OSD1_BLK1_CFG_W4       S6_VCBUS_ADDR(0x1a14)
#define S6_VIU_OSD1_BLK2_CFG_W4       S6_VCBUS_ADDR(0x1a15)
#define S6_VPP_OSD_SC_CTRL0           S6_VCBUS_ADDR(0x1dc8)

/* VIU_OSD1_CTRL_STAT bit 0: layer enable (FBIOSET_POWER). */

#define S6_OSD_CTRL_EN                (1u << 0)

/* Source (pan) and display windows, start/end inclusive. */

#define S6_OSD_WIN_X(end, start)      (((start) & 0x1fffu) | \
                                       (((end) & 0x1fffu) << 16))
#define S6_OSD_WIN_Y(end, start)      S6_OSD_WIN_X(end, start)
#define S6_OSD_DISP_X(end, start)     (((start) & 0xfffu) | \
                                       (((end) & 0xfffu) << 16))
#define S6_OSD_DISP_Y(end, start)     S6_OSD_DISP_X(end, start)

/* Frame address and line stride, both in 16-byte units. */

#define S6_OSD_MIF_ADDR(addr)         ((addr) >> 4)
#define S6_OSD_MIF_STRIDE_MASK        0xfffu
#define S6_OSD_MIF_STRIDE(bytes)      ((((bytes) + 15u) / 16u) & \
                                       S6_OSD_MIF_STRIDE_MASK)

#endif /* __ARCH_ARM64_SRC_S6_HARDWARE_S6_VIU_H */
########## arch/arm64/src/s6/s6_boot.c
/****************************************************************************
 * arch/arm64/src/s6/s6_boot.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <arch/chip/chip.h>

#include "arm64_internal.h"
#include "arm64_mmu.h"
#include "s6_boot.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct arm_mmu_region g_mmu_regions[] =
{
  MMU_REGION_FLAT_ENTRY("S6_DEVICE_REGION",
                        CONFIG_DEVICEIO_BASEADDR,
                        CONFIG_DEVICEIO_SIZE,
                        MT_DEVICE_NGNRNE | MT_RW | MT_SECURE),

  MMU_REGION_FLAT_ENTRY("S6_DRAM_REGION",
                        CONFIG_RAMBANK1_ADDR,
                        CONFIG_RAMBANK1_SIZE,
                        MT_NORMAL | MT_RW | MT_SECURE),
};

/****************************************************************************
 * Public Data
 ****************************************************************************/

const struct arm_mmu_config g_mmu_config =
{
  .num_regions = nitems(g_mmu_regions),
  .mmu_regions = g_mmu_regions,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void arm64_el_init(void)
{
  uint64_t reg;

  if (arm64_current_el() != MODE_EL2)
    {
      return;
    }

  /* Clear the EL1 translation regime before ERET.  The common EL1 setup
   * runs only after the exception-level switch.
   */
  reg = SCTLR_EL1_RES1 | SCTLR_SA_BIT;
#ifndef CONFIG_ARM64_ICACHE_DISABLE
  reg |= SCTLR_I_BIT;
#endif
  write_sysreg(reg, sctlr_el1);

  /* U-Boot can also leave VHE or stage-2 translation enabled. */
  write_sysreg(HCR_RW_BIT, hcr_el2);
  zero_sysreg(vttbr_el2);
  UP_ISB();
}

void arm64_chip_boot(void)
{
  arm64_mmu_init(true);

#ifdef CONFIG_ARM64_PSCI
  arm64_psci_init("smc");
#endif

  s6_board_initialize();

#ifdef USE_EARLYSERIALINIT
  arm64_earlyserialinit();
#endif
}
